import React, { useState } from 'react';
import '../styles/Construcao.css';

const PaginaConstrucao = () => {
  const [activeTab, setActiveTab] = useState('sobre');

  // Dados da construção (pode vir de API depois)
  const construcaoData = {
    meta: 500000,
    arrecadado: 125000,
    progresso: 25,
    dataPrevista: 'Dezembro 2024'
  };

  // Galeria de fotos (substitua pelas suas fotos)
  const fotosConstrucao = [
    {
      id: 1,
      src: 'https://images.unsplash.com/photo-1541888946425-d81bb19240f5?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Início das Obras',
      data: '15/01/2024'
    },
    {
      id: 2,
      src: 'https://images.unsplash.com/photo-1504307651254-35680f356dfd?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Fundação',
      data: '28/02/2024'
    },
    {
      id: 3,
      src: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Estrutura',
      data: '15/03/2024'
    },
    {
      id: 4,
      src: 'https://images.unsplash.com/photo-1465433045946-ba6506ce5a59?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Alvenaria',
      data: '30/03/2024'
    },
    {
      id: 5,
      src: 'https://images.unsplash.com/photo-1519996529937-47d6c1f2c36a?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Cobertura',
      data: '12/04/2024'
    },
    {
      id: 6,
      src: 'https://images.unsplash.com/photo-1503387762606-45b13c6fec4e?ixlib=rb-4.0.3&auto=format&fit=crop&w=500&q=80',
      titulo: 'Acabamentos',
      data: '25/04/2024'
    }
  ];

  // Opções de doação
  const opcoesDoacao = [
    { valor: 50, descricao: 'Contribuição Básica' },
    { valor: 100, descricao: 'Contribuição Especial' },
    { valor: 250, descricao: 'Contribuição Familiar' },
    { valor: 500, descricao: 'Contribuição Missionária' },
    { valor: 1000, descricao: 'Contribuição de Fé' },
    { valor: 0, descricao: 'Outro Valor' }
  ];

  const [valorPersonalizado, setValorPersonalizado] = useState('');

  const handleDoacao = (valor) => {
    if (valor === 0) {
      valor = parseFloat(valorPersonalizado) || 0;
    }
    
    if (valor > 0) {
      // Aqui você integra com o gateway de pagamento
      alert(`Redirecionando para doação de R$ ${valor.toFixed(2)}`);
      // window.location.href = `sua-url-de-pagamento?valor=${valor}`;
    } else {
      alert('Por favor, insira um valor válido');
    }
  };

  return (
    <div className="pagina-construcao">
      {/* Hero Section */}
      <section className="construcao-hero">
        <div className="container">
          <div className="hero-content">
            <h1>🏗️ Novo Templo AD Cavallari</h1>
            <p className="hero-subtitle">Construindo juntos uma casa de adoração e milagres</p>
            
            {/* Card de Progresso */}
            <div className="progresso-card">
              <div className="progresso-info">
                <div className="progresso-text">
                  <h3>Arrecadação da Obra</h3>
                  <div className="valores">
                    <span className="arrecadado">R$ {construcaoData.arrecadado.toLocaleString('pt-BR')}</span>
                    <span className="meta">Meta: R$ {construcaoData.meta.toLocaleString('pt-BR')}</span>
                  </div>
                </div>
                <div className="progresso-porcentagem">
                  {construcaoData.progresso}%
                </div>
              </div>
              
              <div className="progresso-bar">
                <div 
                  className="progresso-fill" 
                  style={{ width: `${construcaoData.progresso}%` }}
                ></div>
              </div>
              
              <div className="progresso-data">
                <span>📅 Previsão de conclusão: {construcaoData.dataPrevista}</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Navegação por Abas */}
      <section className="construcao-tabs">
        <div className="container">
          <div className="tabs-navigation">
            <button 
              className={`tab-btn ${activeTab === 'sobre' ? 'active' : ''}`}
              onClick={() => setActiveTab('sobre')}
            >
              📖 Sobre a Obra
            </button>
            <button 
              className={`tab-btn ${activeTab === 'galeria' ? 'active' : ''}`}
              onClick={() => setActiveTab('galeria')}
            >
              🏗️ Galeria
            </button>
            <button 
              className={`tab-btn ${activeTab === 'doar' ? 'active' : ''}`}
              onClick={() => setActiveTab('doar')}
            >
              💝 Fazer Doação
            </button>
          </div>
        </div>
      </section>

      {/* Conteúdo das Abas */}
      <section className="construcao-conteudo">
        <div className="container">
          
          {/* ABA: SOBRE A OBRA */}
          {activeTab === 'sobre' && (
            <div className="tab-content sobre-content">
              <div className="sobre-grid">
                <div className="sobre-texto">
                  <h2>Uma Casa para a Glória de Deus</h2>
                  <p>
                    Estamos construindo um novo templo para abençoar nossa comunidade e 
                    expandir o Reino de Deus. Este será um lugar de encontro, adoração e 
                    transformação de vidas.
                  </p>
                  
                  <div className="detalhes-obra">
                    <h3>📐 Detalhes da Construção</h3>
                    <ul>
                      <li>✅ <strong>Área total:</strong> 800m²</li>
                      <li>✅ <strong>Capacidade:</strong> 500 pessoas</li>
                      <li>✅ <strong>Salas:</strong> Escola Bíblica, Administração</li>
                      <li>✅ <strong>Estacionamento:</strong> 50 vagas</li>
                      <li>✅ <strong>Acessibilidade:</strong> Total</li>
                    </ul>
                  </div>

                  <div className="versiculo">
                    <blockquote>
                      "Assim diz o Senhor dos Exércitos: A glória desta última casa será maior 
                      do que a da primeira, diz o Senhor dos Exércitos; e neste lugar darei a paz, 
                      diz o Senhor dos Exércitos."
                    </blockquote>
                    <cite>Ageu 2:9</cite>
                  </div>
                </div>
                
                <div className="sobre-imagem">
                  <img 
                    src="https://images.unsplash.com/photo-1545235617-9465d2a55698?ixlib=rb-4.0.3&auto=format&fit=crop&w=600&q=80" 
                    alt="Projeto do novo templo" 
                  />
                </div>
              </div>
            </div>
          )}

          {/* ABA: GALERIA */}
          {activeTab === 'galeria' && (
            <div className="tab-content galeria-content">
              <h2>📸 Acompanhe a Evolução da Obra</h2>
              <p>Veja como está progredindo a construção do nosso novo templo</p>
              
              <div className="galeria-grid">
                {fotosConstrucao.map(foto => (
                  <div key={foto.id} className="galeria-item">
                    <div className="galeria-imagem">
                      <img src={foto.src} alt={foto.titulo} />
                      <div className="galeria-overlay">
                        <div className="galeria-info">
                          <h4>{foto.titulo}</h4>
                          <span>{foto.data}</span>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ABA: DOAÇÕES */}
          {activeTab === 'doar' && (
            <div className="tab-content doacao-content">
              <div className="doacao-grid">
                <div className="doacao-info">
                  <h2>💝 Seja um Construtor com a Gente</h2>
                  <p>
                    Sua contribuição é essencial para concluirmos esta obra abençoada. 
                    Cada oferta é um tijolo na construção do Reino de Deus.
                  </p>
                  
                  <div className="beneficios-doacao">
                    <h3>🎁 Sua doação ajuda em:</h3>
                    <ul>
                      <li>✅ Materiais de construção</li>
                      <li>✅ Mão de obra especializada</li>
                      <li>✅ Acabamentos e mobiliário</li>
                      <li>✅ Sistema de som e iluminação</li>
                      <li>✅ Área infantil e educacional</li>
                    </ul>
                  </div>
                </div>
                
                <div className="doacao-opcoes">
                  <h3>Escolha o valor da sua contribuição:</h3>
                  
                  <div className="opcoes-grid">
                    {opcoesDoacao.map((opcao, index) => (
                      <button
                        key={index}
                        className={`opcao-doacao ${opcao.valor === 0 ? 'personalizado' : ''}`}
                        onClick={() => opcao.valor === 0 ? null : handleDoacao(opcao.valor)}
                      >
                        {opcao.valor === 0 ? (
                          <div className="input-personalizado">
                            <span>R$</span>
                            <input
                              type="number"
                              placeholder="0,00"
                              value={valorPersonalizado}
                              onChange={(e) => setValorPersonalizado(e.target.value)}
                              onKeyPress={(e) => e.key === 'Enter' && handleDoacao(0)}
                            />
                            <button 
                              className="btn-doar-personalizado"
                              onClick={() => handleDoacao(0)}
                            >
                              Doar
                            </button>
                          </div>
                        ) : (
                          <>
                            <div className="valor">R$ {opcao.valor}</div>
                            <div className="descricao">{opcao.descricao}</div>
                          </>
                        )}
                      </button>
                    ))}
                  </div>
                  
                  <div className="info-pagamento">
                    <p>💳 Pagamento 100% seguro via PIX ou Cartão</p>
                    <small>Seus dados estão protegidos e a transação é criptografada</small>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* CTA Final */}
      <section className="construcao-cta">
        <div className="container">
          <div className="cta-content">
            <h2>Juntos na Obra do Senhor</h2>
            <p>Sua participação faz parte desta história de fé e milagres</p>
            <button 
              className="btn-cta"
              onClick={() => setActiveTab('doar')}
            >
              Quero Contribuir
            </button>
          </div>
        </div>
      </section>
    </div>
  );
};

export default PaginaConstrucao;
